# Autogenerated wrapper script for Lavapipe_jll for aarch64-apple-darwin
export libvulkan_lvp, lvp_icd

using Zlib_jll
using Expat_jll
using Zstd_jll
using CompilerSupportLibraries_jll
JLLWrappers.@generate_wrapper_header("Lavapipe")
JLLWrappers.@declare_library_product(libvulkan_lvp, "@rpath/libvulkan_lvp.dylib")
JLLWrappers.@declare_file_product(lvp_icd)
function __init__()
    JLLWrappers.@generate_init_header(Zlib_jll, Expat_jll, Zstd_jll, CompilerSupportLibraries_jll)
    JLLWrappers.@init_library_product(
        libvulkan_lvp,
        "lib/libvulkan_lvp.dylib",
        RTLD_LAZY | RTLD_DEEPBIND,
    )

    JLLWrappers.@init_file_product(
        lvp_icd,
        "share/vulkan/icd.d/lvp_icd.json",
    )

    JLLWrappers.@generate_init_footer()
    let sep = Sys.iswindows() ? ';' : ':',
    found = split(get(ENV, "VK_ADD_DRIVER_FILES", ""), sep; keepempty=false)
    if !(lvp_icd in found)
        ENV["VK_ADD_DRIVER_FILES"] = join(vcat(found, lvp_icd), sep)
    end
end

end  # __init__()
